{
  "name": "Aged, Blind, and Disabled Medicaid",
  "eligibility": {
    "age": 65,
    "income_limits": {
      "summary": "West Virginia’s ABD Medicaid has two practical paths: regular SSI-related ABD eligibility and medically needy/spend-down coverage for people whose income is above the regular limit.[1][5][8]",
      "regular_eligibility_limit": {
        "single": "$994/month in 2026 for SSI-related ABD coverage.[10][15]",
        "couple": "$1,491/month in 2026 for SSI-related ABD coverage.[10][15]",
        "notes": "These figures are reflected in West Virginia ABD eligibility summaries and KFF state data; the state also notes that SSI income beneficiaries are automatically eligible for Medicaid coverage.[1][10][15]"
      },
      "medically_needy_or_spend_down": {
        "summary": "If income is above the regular limit, aged/blind/disabled applicants may still qualify by spending down to the medically needy income level using incurred medical expenses.[5][8]",
        "amount": "West Virginia’s long-term care/ABD materials describe a 300% SSI-based threshold of $2,901/month effective January 2025 for certain long-term-care coverage, with the medically needy route available when monthly nursing care costs exceed the Medically Needy Income Limit and all other requirements are met.[8]",
        "notes": "The exact spend-down threshold can vary by coverage type; ABD coverage for community medical care and long-term-care coverage are not identical, so families need to check the specific category being pursued.[5][8]"
      }
    },
    "asset_limits": {
      "summary": "ABD Medicaid is asset-tested unless the person is automatically eligible through SSI-related rules.[5][8]",
      "limits": {
        "single": "$2,000 countable assets.[5][8]",
        "couple": "$3,000 countable assets.[5][8]"
      },
      "what_counts": [
        "Cash, bank accounts, and other liquid resources are generally countable under Medicaid asset rules.",
        "Vehicles, a home, and certain burial-related resources may be exempt depending on Medicaid rules and how they are titled."
      ],
      "what_is_exempt": [
        "The home may be exempt if it is the applicant’s principal residence and equity rules are satisfied.",
        "One vehicle is commonly exempt under Medicaid rules.",
        "Certain personal belongings and some burial funds/arrangements may be exempt."
      ],
      "notes": "The sources confirm the dollar limits but do not spell out every exemption in the ABD summary pages, so the exact exempt-resource list is governed by West Virginia Medicaid resource rules in the eligibility manual.[5][8]"
    },
    "other_requirements": [
      "Must be aged, blind, or disabled.[1][3][5][10]",
      "Must meet West Virginia Medicaid financial eligibility rules for the coverage category sought.[1][5][8]",
      "Some applicants must also meet functional/medical criteria if applying for long-term-care or waiver-style services rather than basic coverage.[8]",
      "SSI beneficiaries are automatically eligible for Medicaid coverage and do not need to apply through the county office for that coverage path.[1]",
      "Eligibility is determined by West Virginia Department of Human Services/DoHS workers in county offices.[1][13]"
    ]
  },
  "benefits": {
    "type": "service",
    "value": "This program is Medicaid health coverage for aged, blind, or disabled people. It covers routine medical care such as physician visits, prescription drugs, emergency room care, and short-term hospital stays; in long-term-care pathways it can also pay for nursing home care and, for eligible people, in-home care that meets a nursing-home level of care.[8][10]",
    "varies_by": "fixed"
  },
  "application": {
    "methods": [
      "Online through WV PATH / West Virginia Medicaid application portal.[10][9]",
      "By phone through the Customer Service Center at 877-716-1212.[10]",
      "In person at a local county Department of Health and Human Resources/DoHS office.[1][10]",
      "By paper application using the Application for Adult Medicaid (DFA-MA-1).[2]"
    ],
    "processing_time": "No exact statewide processing-time guarantee was identified in the gathered sources. Eligibility is handled by county offices, so timing can vary by office workload and by whether the case needs disability, medical, or long-term-care review.[1][13]",
    "waitlist": "For basic ABD Medicaid, no waitlist is indicated; Medicaid is an entitlement if eligibility is met.[10] Long-term-care or waiver-related services may involve different eligibility or service-authority rules, but the gathered sources did not show a county-specific ABD waitlist.",
    "forms": [
      "DFA-MA-1 Application for Adult Medicaid[2]",
      "Healthcare Application for Individual (for one person) / WV PATH application route[9]"
    ],
    "documents": [
      "Proof of identity and West Virginia residency",
      "Proof of age or disability/blindness status",
      "Income proof such as Social Security, pension, wages, or benefit award letters",
      "Bank statements and other asset/resource records",
      "Mortgage, rent, utility, and insurance information if asked",
      "Medical bills and receipts if pursuing spend-down or medically needy eligibility",
      "Information about Medicare or other health coverage",
      "Spouse information if married, because spousal rules can affect eligibility and allowances"
    ]
  },
  "geography": {
    "statewide": true,
    "restrictions": "Statewide Medicaid coverage, administered through county offices; no county-only restriction was identified for ABD Medicaid itself.[1][13]",
    "regional_variations": "The core ABD Medicaid rules are statewide, but application handling, case processing speed, and local office practice can vary by county office.[1][13]",
    "offices_or_providers": [
      "Local county Department of Health and Human Resources/DoHS offices",
      "WV Bureau for Medical Services statewide Medicaid administration",
      "WV PATH online application portal"
    ]
  },
  "official_source": "https://dhhr.wv.gov/bms/BMSPUB/Documents/Guide%20to%20Medicaid%202025.pdf",
  "gotchas": [
    "People often confuse regular ABD Medicaid with long-term-care Medicaid; the financial rules can differ, especially for nursing-home or in-home care pathways.[5][8]",
    "A person may be automatically eligible through SSI, which means no separate county-office application is needed for that Medicaid path.[1]",
    "If income is above the standard limit, spend-down may still make someone eligible, but only after medical expenses are applied correctly and the case is evaluated under the right coverage category.[5][8]",
    "Asset limits still matter even when income is low; families often overlook bank accounts, CDs, and jointly held resources.[5][8]",
    "The state uses county offices for eligibility decisions, so two families can experience different turnaround times depending on office workload.[1][13]",
    "The Medicaid category matters: basic ABD coverage, medically needy coverage, and long-term-care coverage are related but not identical programs.[5][8]"
  ],
  "data_shape_notes": "This program is state Medicaid coverage with fixed income and asset limits for ABD eligibility, plus a separate spend-down path for people over the income limit; it is not household-size tiered like SNAP, but married-couple rules and long-term-care subcategories change the financial test.[5][8][10]"
}
